WITH cleaned AS (SELECT *, age * credit_limit AS age_times_credit_limit, ROUND(credit_limit, 2) AS credit_limit_rounded, COALESCE(city, 'N/A') AS resolved_city FROM customers WHERE city IS NOT NULL AND signup_date <= '2024-03-01'), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY signup_date, id) AS rank_in_group FROM cleaned QUALIFY rank_in_group = 1), kept_keys AS (SELECT id, city FROM deduped INTERSECT ALL SELECT id, city FROM customers WHERE city IN ('Singapore', 'New York', 'Bangkok')), reconciled AS (SELECT s.* FROM deduped s INNER JOIN kept_keys k ON s.id = k.id AND s.city = k.city), with_windows AS (SELECT *, AVG(credit_limit_rounded) OVER (PARTITION BY country) AS country_avg_credit_limit_rounded FROM reconciled) SELECT name, email, country, city, segment, credit_limit, age, age_times_credit_limit, credit_limit_rounded FROM with_windows ORDER BY segment DESC NULLS FIRST, credit_limit_rounded DESC
